// shared/src/rng.ts
function hashString(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = h << 13 | h >>> 19;
  }
  h = Math.imul(h ^ h >>> 16, 2246822507);
  h = Math.imul(h ^ h >>> 13, 3266489909);
  return (h ^= h >>> 16) >>> 0;
}
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = a + 1831565813 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function createActionRng(civSeed, actionType, nonce) {
  const seed = hashString(`${civSeed}::${actionType}::${nonce}`);
  return mulberry32(seed);
}
function weightedPick(rng, weights) {
  const total = weights.reduce((a, b) => a + b, 0);
  let r = rng() * total;
  for (let i = 0; i < weights.length; i++) {
    r -= weights[i];
    if (r <= 0) return i;
  }
  return weights.length - 1;
}
function rngInt(rng, min, max) {
  return min + Math.floor(rng() * (max - min + 1));
}
function rngPick(rng, arr) {
  return arr[Math.floor(rng() * arr.length)];
}
function generateSeed(extra = "") {
  const t = Date.now().toString(36);
  const r = Math.random().toString(36).slice(2, 10);
  return hashString(`${t}-${r}-${extra}`).toString(16).padStart(8, "0") + r;
}

