var SYSTEM_PREFIX = ["\u041A\u0435\u043F\u043B\u0435\u0440", "\u0422\u0440\u0430\u043F\u043F\u0438\u0441\u0442", "\u041F\u0440\u043E\u043A\u0441\u0438\u043C\u0430", "\u041B\u044E\u0442\u0435\u043D", "\u0412\u043E\u043B\u044C\u0444", "\u0411\u0430\u0440\u043D\u0430\u0440\u0434", "\u0420\u043E\u0441\u0441", "\u0413\u043B\u0438\u0437\u0435", "HR", "TOI"];
