var ARTIFACTS_BY_KEY = Object.fromEntries(
  ARTIFACT_CATALOG.map((a) => [a.key, a])
);
var ARTIFACTS_BY_RARITY = {
  common: ARTIFACT_CATALOG.filter((a) => a.rarity === "common"),
  rare: ARTIFACT_CATALOG.filter((a) => a.rarity === "rare"),
  legendary: ARTIFACT_CATALOG.filter((a) => a.rarity === "legendary"),
  mythic: ARTIFACT_CATALOG.filter((a) => a.rarity === "mythic")
};
var ARTIFACT_SLOT_LIMIT = 20;
function sumArtifactEffects(keys) {
  const out = {};
  for (const key of keys) {
    const def = ARTIFACTS_BY_KEY[key];
    if (!def) continue;
    const e = def.effects;
    out.heProductionBonus = (out.heProductionBonus ?? 0) + (e.heProductionBonus ?? 0);
    out.antimatterProductionBonus = (out.antimatterProductionBonus ?? 0) + (e.antimatterProductionBonus ?? 0);
    out.darkMatterProductionBonus = (out.darkMatterProductionBonus ?? 0) + (e.darkMatterProductionBonus ?? 0);
    out.darkEnergyProductionBonus = (out.darkEnergyProductionBonus ?? 0) + (e.darkEnergyProductionBonus ?? 0);
    out.fermionsProductionBonus = (out.fermionsProductionBonus ?? 0) + (e.fermionsProductionBonus ?? 0);
    out.allProductionBonus = (out.allProductionBonus ?? 0) + (e.allProductionBonus ?? 0);
    out.radarBonus = (out.radarBonus ?? 0) + (e.radarBonus ?? 0);
    out.localScanCostReduction = (out.localScanCostReduction ?? 0) + (e.localScanCostReduction ?? 0);
    out.probeDurationReduction = (out.probeDurationReduction ?? 0) + (e.probeDurationReduction ?? 0);
    out.allExpeditionDurationReduction = (out.allExpeditionDurationReduction ?? 0) + (e.allExpeditionDurationReduction ?? 0);
    if (e.unlock4DRift) out.unlock4DRift = true;
    if (e.expeditionReroll) out.expeditionReroll = true;
    if (e.levelUpEcho) out.levelUpEcho = true;
    out.revealSectors = (out.revealSectors ?? 0) + (e.revealSectors ?? 0);
    out.combatAttackBonus = (out.combatAttackBonus ?? 0) + (e.combatAttackBonus ?? 0);
    out.combatDefenseBonus = (out.combatDefenseBonus ?? 0) + (e.combatDefenseBonus ?? 0);
  }
  return out;
}

