            antimatter: res.antimatter + Math.floor(def.cost.antimatter * 0.4),
            darkEnergy: res.darkEnergy + Math.floor(def.cost.darkEnergy * 0.4),
            darkMatter: res.darkMatter + Math.floor(def.cost.darkMatter * 0.4),
