async function debugResolveAllCombat(userId) {
  const civRow = await prisma.civilization.findUnique({ where: { userId } });
  if (!civRow) throw new AppError("CIV_NOT_FOUND", "\u0426\u0438\u0432\u0438\u043B\u0438\u0437\u0430\u0446\u0438\u044F \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430", 404);
  await prisma.$transaction(async (tx) => {
    const past = new Date(Date.now() - 1e3);
    await tx.combatAction.updateMany({
      where: {
        attackerCivilizationId: civRow.id,
        status: { in: ["PREPARING", "IN_TRANSIT"] }
      },
      data: {
        prepFinishesAt: past,
        transitFinishesAt: past
      }
    });
    const civ = await tx.civilization.findUnique({
      where: { id: civRow.id },
      include: {
        resources: true,
        buildings: true,
        artifacts: true,
        discoveredAnomalies: true,
        expeditions: { where: { status: "active" }, take: 1 },
        journal: { take: 1 }
      }
    });
    if (!civ) return;
    const actions = await tx.combatAction.findMany({
      where: {
        attackerCivilizationId: civ.id,
        status: { in: ["PREPARING", "IN_TRANSIT"] }
      }
    });
    for (const a of actions) {
      if (a.status === "PREPARING") {
        const def = ATTACK_TYPES_BY_TYPE[a.attackType];
        if (def?.hasTransit) {
          await tx.combatAction.update({
            where: { id: a.id },
            data: { status: "IN_TRANSIT", transitFinishesAt: past }
          });
        }
      }
      await resolveActionInTx(tx, civ, a.id);
    }
  });
  const state = await getUserCivilizationState(userId);
  if (!state) throw new AppError("CIV_NOT_FOUND", "\u0426\u0438\u0432\u0438\u043B\u0438\u0437\u0430\u0446\u0438\u044F \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430", 404);
  return state;
}
async function debugGrantCombatResources(userId) {
  const civ = await prisma.civilization.findUnique({
    where: { userId },
    include: { resources: true }
  });
  if (!civ?.resources) throw new AppError("CIV_NOT_FOUND", "\u0426\u0438\u0432\u0438\u043B\u0438\u0437\u0430\u0446\u0438\u044F \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430", 404);
  await prisma.resourceState.update({
    where: { civilizationId: civ.id },
    data: {
      highEnergyCapacity: Math.max(civ.resources.highEnergyCapacity, 8e4),
      antimatterCapacity: Math.max(civ.resources.antimatterCapacity, 5e3),
      darkEnergyCapacity: Math.max(civ.resources.darkEnergyCapacity, 5e3),
      darkMatterCapacity: Math.max(civ.resources.darkMatterCapacity, 5e3),
      fermionsCapacity: Math.max(civ.resources.fermionsCapacity, 2e3),
      highEnergy: Math.min(8e4, civ.resources.highEnergy + 3e4),
      antimatter: Math.min(5e3, civ.resources.antimatter + 1e3),
      darkEnergy: Math.min(5e3, civ.resources.darkEnergy + 500),
      darkMatter: Math.min(5e3, civ.resources.darkMatter + 500),
      fermions: Math.min(2e3, civ.resources.fermions + 200)
    }
  });
  if (civ.level < 20) {
    await prisma.civilization.update({
      where: { id: civ.id },
      data: { level: 20 }
    });
  }
  const state = await getUserCivilizationState(userId);
  if (!state) throw new AppError("CIV_NOT_FOUND", "\u0426\u0438\u0432\u0438\u043B\u0438\u0437\u0430\u0446\u0438\u044F \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430", 404);
  return state;
}

