// server/src/services/prosperityService.ts
async function computeAndStoreProsperity(tx, civ) {
  if (!civ.resources) return civ.level * 100;
  const buildings = buildingsToState(civ.buildings);
  const contacts = civ.contactsObserved ?? [];
  const contactsDestroyed = contacts.filter((c) => c.isDestroyed || c.status === "destroyed").length;
  const contactsDetected = Math.max(0, contacts.length - contactsDestroyed);
  const reports = await tx.combatReport.findMany({
    where: { attackerCivilizationId: civ.id },
    select: { outcome: true }
  });
  let combatDestroyWins = 0;
  let combatDamageWins = 0;
  for (const r of reports) {
    if (r.outcome === "HIT_DESTROYED") combatDestroyWins += 1;
    else if (r.outcome === "HIT_LIGHT" || r.outcome === "HIT_MODERATE" || r.outcome === "HIT_HEAVY" || r.outcome === "COUNTERATTACKED") {
      combatDamageWins += 1;
    }
  }
  const score = calculateProsperityScore({
    level: civ.level,
    buildings,
    resources: {
      highEnergy: civ.resources.highEnergy,
      antimatter: civ.resources.antimatter,
      darkEnergy: civ.resources.darkEnergy,
      darkMatter: civ.resources.darkMatter,
      fermions: civ.resources.fermions
    },
    artifactRarities: civ.artifacts.map((a) => a.rarity),
    contactsDetected,
    contactsDestroyed,
    combatDamageWins,
    combatDestroyWins,
    successfulExpeditions: civ.successfulExpeditions,
    totalHighEnergyMined: civ.totalHighEnergyMined,
    isDestroyed: !!civ.isDestroyed
  });
  await tx.civilization.update({
    where: { id: civ.id },
    data: { prosperityScore: score }
  });
  return score;
}

// server/src/services/gameService.ts
function capsFor(buildings, level, resources) {
  const base = resourceCapacities(
    buildings,
    level,
    resources ? shopBonusesFromResourceState(resources) : {}
  );
  if (!resources) return base;
  return {
    highEnergy: Math.max(base.highEnergy, resources.highEnergyCapacity ?? 0),
    antimatter: Math.max(base.antimatter, resources.antimatterCapacity ?? 0),
    darkEnergy: Math.max(base.darkEnergy, resources.darkEnergyCapacity ?? 0),
    darkMatter: Math.max(base.darkMatter, resources.darkMatterCapacity ?? 0),
    fermions: Math.max(base.fermions, resources.fermionsCapacity ?? 0)
  };
}
